/* Exact static boundary-route descriptors. One undirected route counted once.
 * Closed internal loops are inaccessible from the boundary and excluded.
 */
function traceTopology(genome,cols,rows){const routes=[],visited=new Set(),exits=[[1,0,3,2],[3,2,1,0],[2,3,0,1]],dx=[0,1,0,-1],dy=[-1,0,1,0],ports=[];for(let x=0;x<cols;x++){ports.push([x,0,0],[x,rows-1,2])}for(let y=0;y<rows;y++){ports.push([cols-1,y,1],[0,y,3])}const portKey=(x,y,e)=>(y*cols+x)*4+e;for(let [sx,sy,se] of ports){let start=portKey(sx,sy,se);if(visited.has(start))continue;visited.add(start);let x=sx,y=sy,entry=se,length=0,tiles=0;while(true){if(++tiles>cols*rows*2)throw Error('Invalid boundary route: exceeded topology bound');const exit=exits[genome[y*cols+x]][entry];length+=(entry+2)%4===exit?1:Math.PI/4;let nx=x+dx[exit],ny=y+dy[exit];if(nx<0||nx>=cols||ny<0||ny>=rows){visited.add(portKey(x,y,exit));break}x=nx;y=ny;entry=(exit+2)%4}routes.push({length,tiles})}return{meanPath:routes.reduce((s,r)=>s+r.length,0)/routes.length,routeCount:routes.length,shortCounts:Array.from({length:8},(_,i)=>routes.filter(r=>r.tiles<=i+1).length),maxPath:Math.max(...routes.map(r=>r.length))}}
